"""Delivered native-review entry point and bounded calibration controls."""
import json
from html import escape


def review_page(prefix):
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review and calibration</title><link rel="stylesheet" href="'''+escape(prefix)+'''/static/app.css"></head><body class="langfuse-theme bank-presenter"><main><nav><a href="'''+escape(prefix)+'''/">Customer assistant</a> · <a href="'''+escape(prefix)+'''/manage/judges">Policy reconciliation</a></nav><h1 class="lf-heading">Review and calibration</h1><p id="notice" role="status"></p>
<section class="lf-frame corner-box-corners"><h2>Pending reviews</h2><p>Review delivered answers in Langfuse using your own account. Completed reviews are preserved. Preparing work adds at most 20 pending subjects and makes no model calls.</p><p id="rubric"></p><button class="lf-button lf-button__label" id="prepare">Prepare 10 pending reviews</button><button class="lf-button lf-button__label" id="refresh">Refresh status</button><p id="queue"></p></section>
<section class="lf-frame corner-box-corners"><h2>Calibration</h2><p>The fixed cohort has 16 constructed reference labels. Optional native ANNOTATION scores identify actual user reviews. Repeated scores from one account do not create additional reviewers. Disagreements and invalid labels remain unresolved.</p>
<form id="plan"><label>Judge model <input name="model" required maxlength="120" placeholder="Model available to the selected provider"></label><label><input name="reviews" type="checkbox" checked>Include reviewed answers</label><button class="lf-button lf-button__label">Prepare calibration</button></form>
<p id="calibration-status">No calibration prepared.</p><div id="scope"></div><p><label><input id="cost" type="checkbox">I confirm the displayed model and cost scope.</label></p><button class="lf-button lf-button__label" id="start" disabled>Start calibration</button><button class="lf-button lf-button__label" id="cancel" disabled>Cancel calibration</button><button class="lf-button lf-button__label" id="readback" disabled>Verify native results</button>
<p>Cancellation stops new calls. An in-flight request can finish and incur cost. Each action runs once; interrupted or uncertain actions require native inspection before preparing another. Results and receipts are retained for this Companion's lifetime; remote experiments remain in Langfuse.</p>
<div id="results"></div><details><summary>Frozen evidence</summary><div id="evidence"></div></details><details><summary>Unresolved reviews</summary><div id="unresolved"></div></details></section>
<section class="lf-frame corner-box-corners"><h2>Previous calibrations</h2><div id="history"></div></section>
</main><script>
const base='''+json.dumps(prefix+'/manage/reviews')+''';let current=null,poll=null;const el=id=>document.getElementById(id);
function node(tag,text,parent){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(parent)parent.append(n);return n;}
function link(url,text,parent){if(!url)return;const a=node('a',text,parent);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}
function render(v){el('rubric').textContent=v.rubric;const q=el('queue');q.replaceChildren();if(v.queue){q.append(`${v.queue.pending} pending · ${v.queue.completed} completed · ${v.queue.shortfall} missing from requested backlog. `);link(v.queue.url,'Open native review queue',q);}else q.textContent='No review queue prepared.';
 current=v.calibration;const c=current;el('start').disabled=!c||c.status!=='planned';el('cancel').disabled=c?.status!=='running';el('readback').disabled=!c?.outcomes||c.status==='running';el('plan').querySelector('button').disabled=c?.status==='running';el('prepare').disabled=c?.status==='running';
 el('calibration-status').textContent=c?`${c.status} · ${c.completed||0} of ${c.max_model_calls} rows processed · ${c.model_calls||0} model calls started · native evidence: ${c.native_status}${c.error?' · '+c.error:''}`:'No calibration prepared.';
 for(const id of ['scope','results','evidence','unresolved','history'])el(id).replaceChildren();
 if(c){node('p',`${c.provider} · ${c.model} · rubric version ${c.rubric_version} · ${c.constructed_rows} constructed rows · ${c.annotation_rows} reviewed rows.`,el('scope'));node('p',c.cost_scope,el('scope'));link(c.rubric_url,'Open exact rubric',el('scope'));node('p',`Snapshot ${c.snapshot_hash}`,el('scope'));link(c.experiment_url,'Open native experiment',el('results'));
 if(c.metrics){for(const [key,label] of [['constructed','Constructed references'],['native_annotation','Native user annotations']]){const m=c.metrics[key];node('p',`${label}: ${m.valid} valid of ${m.total}; ${m.invalid_or_unresolved} invalid or unresolved; ${m.matches} matching; accuracy ${m.accuracy===null?'undefined':(100*m.accuracy).toFixed(1)+'%'}.`,el('results'));}node('p','These are measured agreements on the selected evidence. Constructed references are not independent human ground truth. No deployment quality threshold is inferred.',el('results'));}
 const table=node('table',undefined,el('results'));const head=node('tr',undefined,table);for(const title of ['Reference source','Expected','Actual','Status','Evidence'])node('th',title,head);for(const r of c.outcomes||[]){const tr=node('tr',undefined,table);node('td',r.provenance,tr);node('td',String(r.expected_output),tr);node('td',r.actual===null?'Unresolved':String(r.actual),tr);node('td',r.status+(r.error?' · '+r.error:''),tr);const td=node('td',undefined,tr);link(r.result_url,'Result',td);td.append(' · ');link(r.source_url,'Source',td);}
 for(const r of c.rows){const d=node('details',undefined,el('evidence'));node('summary',r.id+' · '+r.provenance,d);node('pre',JSON.stringify({input:r.input,reference:r.expected_output,reviewer_ids:r.reviewer_ids,score_ids:r.score_ids},null,2),d);link(r.source_url,'Open source',d);}for(const r of c.unresolved_reviews){node('p',r.status+' · '+r.observation_id,el('unresolved'));link(r.source_url,'Inspect review source',el('unresolved'));}
 }
 for(const r of v.calibration_history||[]){const p=node('p',r.request_id+' · '+r.status+' · '+r.model+' · ',el('history'));link(r.experiment_url,'Native experiment',p);}
 if(c?.status==='running'&&!poll)poll=setTimeout(()=>{poll=null;call('/status');},1000);
}
async function call(path,body){try{const r=await fetch(base+path,body!==undefined?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const raw=await r.text();let v=null;try{v=JSON.parse(raw);}catch{}if(!r.ok)throw Error(typeof v?.detail==='string'?v.detail:(r.status===429?'Request rate limit reached (HTTP 429). Wait, then Refresh status before retrying.':`Request failed (HTTP ${r.status}). Refresh status before retrying.`));if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Response unavailable. Outcome unconfirmed. Refresh status before retrying.');render(v);el('notice').textContent='Status updated.';return v;}catch(e){el('notice').textContent=e.message;}}
el('prepare').onclick=()=>call('/prepare',{request_id:crypto.randomUUID(),pending:10});el('refresh').onclick=()=>call('/status');
el('plan').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);el('cost').checked=false;call('/plan',{request_id:crypto.randomUUID(),model:f.get('model'),include_reviews:f.get('reviews')==='on'});};
el('start').onclick=()=>{if(current)call('/start',{request_id:current.request_id,snapshot_hash:current.snapshot_hash,cost_acknowledged:el('cost').checked});};el('cancel').onclick=()=>call('/cancel',{});el('readback').onclick=()=>call('/readback',{});call('/status');
</script></body></html>'''
